// Token Launch Radar dashboard — static, zero network.
// Data comes from data.js (window.TOKEN_RADAR_BOARD), generated by main.ts.
// Rows are compact arrays; farm steps come from the per-category templates in
// the same file, filled in per row — the same strings board.json carries.
// Deep links: ?protocol=<slug> opens a detail view; ?category=&chain=
// &confidence=&q=&sort= pre-set the board filters.
// NOTE: this file must contain no web addresses with a scheme (gate rule):
// links are shown as plain text, never as anchors.

(function () {
  "use strict";
  var BOARD = window.TOKEN_RADAR_BOARD;
  if (!BOARD) {
    document.body.innerHTML = "<p style='padding:40px'>Board data failed to load (data.js missing).</p>";
    return;
  }
  // Compact row: [slug, name, category, tvl, implied, multiple, peers,
  // fallback, confidence, primaryChain, change7d, ageYears, farmCost]
  var ROWS = BOARD.rows.map(function (a, i) {
    return {
      slug: a[0], name: a[1], category: a[2], tvl: a[3], implied: a[4],
      multiple: a[5], peers: a[6], fallback: a[7], confidence: a[8],
      chain: a[9], change7d: a[10], age: a[11], cost: a[12], rank: i + 1,
    };
  });
  var META = BOARD.meta;
  var TEMPLATES = BOARD.templates;
  var PER_PAGE = 25;
  var CADENCE = "2-3 sessions a week for 6-12 weeks";

  var params = new URLSearchParams(window.location.search);
  var state = {
    q: params.get("q") || "",
    category: params.get("category") || "",
    chain: params.get("chain") || "",
    confidence: params.get("confidence") || "",
    sort: params.get("sort") || "implied",
    page: Math.max(1, parseInt(params.get("page") || "1", 10) || 1),
    detail: params.get("protocol") || "",
  };

  var $ = function (id) { return document.getElementById(id); };
  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function fmtUsd(n) {
    if (n >= 1e9) return "$" + (n / 1e9).toFixed(2) + "B";
    if (n >= 1e6) return "$" + (n / 1e6).toFixed(1) + "M";
    if (n >= 1e3) return "$" + (n / 1e3).toFixed(0) + "K";
    return "$" + Math.round(n);
  }
  function fmtPct(x) {
    if (x == null || isNaN(x)) return "<span class='flat'>—</span>";
    var cls = x > 0 ? "pos" : x < 0 ? "neg" : "flat";
    var sign = x > 0 ? "+" : "";
    return "<span class='" + cls + "'>" + sign + (x).toFixed(1) + "%</span>";
  }
  function farmSteps(r) {
    var tpl = (r.category && TEMPLATES[r.category]) || TEMPLATES.__generic;
    return tpl.map(function (t) {
      return t.replaceAll("{name}", r.name)
        .replaceAll("{chain}", r.chain || "its main chain")
        .replaceAll("{slug}", r.slug)
        .replaceAll("{cost}", r.cost);
    });
  }
  function rationale(r) {
    var s = r.name + " records no token and holds " + fmtUsd(r.tvl) + " of TVL";
    if (r.change7d != null) s += " (" + (r.change7d > 0 ? "+" : "") + r.change7d.toFixed(1) + "% over 7 days)";
    if (r.age != null) s += " after " + r.age + " years live";
    s += ". " + (r.category || "Uncategorized") + " tokens trade at a median " + r.multiple.toFixed(2) +
      "x market-cap/TVL across " + r.peers + " tokenized peer" + (r.peers === 1 ? "" : "s") +
      (r.fallback ? " (thin peer set — median of category medians used)" : "") +
      ", so the launch is implied at " + fmtUsd(r.implied) + ".";
    return s;
  }

  // ---- header / stats ----
  var fetched = (META.snapshot.as_of || "").slice(0, 10);
  $("snapshotLine").textContent =
    "Snapshot: DefiLlama protocols · " + META.snapshot.protocols.toLocaleString() + " protocols · " +
    "watchlist " + META.snapshot.watchlist + " · sealed " + fetched;
  $("footSnapshot").textContent = "sealed " + fetched + " (sha256 " + (META.snapshot.sha256 || "").slice(0, 12) + "…)";
  $("stats").innerHTML =
    statCard(String(META.totals.rows), "tokenless protocols ranked", "watchlist " + META.totals.watchlist_covered + " of " + META.snapshot.watchlist + " covered") +
    statCard(fmtUsd(META.totals.tvl_usd), "TVL tracked on the board", "sum of the ranked protocols") +
    statCard(fmtUsd(META.totals.implied_usd), "combined implied value", "sum of all implied launch values", true);
  function statCard(value, label, sub, accent) {
    return "<div class='stat'><div class='label'>" + esc(label) + "</div>" +
      "<div class='value" + (accent ? " accent" : "") + "'>" + esc(value) + "</div>" +
      "<div class='sub'>" + esc(sub) + "</div></div>";
  }

  // ---- filter options ----
  var cats = [...new Set(ROWS.map(function (r) { return r.category; }).filter(Boolean))].sort();
  var chains = [...new Set(ROWS.map(function (r) { return r.chain; }).filter(Boolean))].sort();
  fillSelect($("category"), cats);
  fillSelect($("chain"), chains);
  function fillSelect(sel, values) {
    values.forEach(function (v) {
      var o = document.createElement("option");
      o.value = v; o.textContent = v; sel.appendChild(o);
    });
  }
  $("q").value = state.q;
  $("category").value = state.category;
  $("chain").value = state.chain;
  $("confidence").value = state.confidence;
  $("sort").value = state.sort;

  // ---- methodology ----
  var m = META.method;
  $("methodBody").innerHTML =
    methodCard("1 · Tokenless, verified", "A protocol counts as tokenless only if the snapshot records neither a CoinGecko id nor a token symbol for it. " + m.token_test) +
    methodCard("2 · Implied value from peers", m.implied_value) +
    methodCard("3 · Winsorized multiples", m.winsor + " " + m.board) +
    methodCard("4 · Farm plans", "Every row carries six concrete steps: what to do, what it costs in gas, and how long to keep at it (" + CADENCE + "). Steps come from the protocol's own category, chain and record — never from a hardcoded list of names.");
  function methodCard(h, p) {
    return "<div class='card'><h4>" + esc(h) + "</h4><p>" + esc(p) + "</p></div>";
  }

  // ---- filtering / sorting / paging ----
  function filtered() {
    var q = state.q.trim().toLowerCase();
    var list = ROWS.filter(function (r) {
      if (q && (r.name + " " + (r.category || "") + " " + (r.chain || "")).toLowerCase().indexOf(q) === -1) return false;
      if (state.category && r.category !== state.category) return false;
      if (state.chain && r.chain !== state.chain) return false;
      if (state.confidence && r.confidence !== state.confidence) return false;
      return true;
    });
    var sorters = {
      implied: function (a, b) { return b.implied - a.implied; },
      tvl: function (a, b) { return b.tvl - a.tvl; },
      multiple: function (a, b) { return b.multiple - a.multiple; },
      name: function (a, b) { return a.name.localeCompare(b.name); },
    };
    list.sort(sorters[state.sort] || sorters.implied);
    return list;
  }

  function renderBoard() {
    var list = filtered();
    var pages = Math.max(1, Math.ceil(list.length / PER_PAGE));
    if (state.page > pages) state.page = pages;
    var start = (state.page - 1) * PER_PAGE;
    var pageRows = list.slice(start, start + PER_PAGE);
    $("resultCount").textContent =
      list.length.toLocaleString() + " protocol" + (list.length === 1 ? "" : "s") +
      " · page " + state.page + " of " + pages;
    $("rows").innerHTML = pageRows.map(function (r) {
      return "<tr data-key='" + esc(r.slug) + "'>" +
        "<td class='num'>" + r.rank + "</td>" +
        "<td class='name'><b>" + esc(r.name) + "</b><span class='chains'>" + esc(r.chain || "—") + "</span></td>" +
        "<td>" + esc(r.category || "—") + "</td>" +
        "<td class='num'>" + fmtUsd(r.tvl) + "</td>" +
        "<td class='num implied'>" + fmtUsd(r.implied) + "</td>" +
        "<td class='num'>" + r.multiple.toFixed(2) + "× <span class='mult-note'>(" + r.peers + " peers" + (r.fallback ? ", fallback" : "") + ")</span></td>" +
        "<td>" + esc(r.chain || "—") + "</td>" +
        "<td class='num'>" + fmtPct(r.change7d) + "</td>" +
        "<td><span class='badge " + r.confidence + "'>" + r.confidence + "</span></td>" +
        "</tr>";
    }).join("") || "<tr><td colspan='9' style='text-align:center;color:var(--muted)'>No protocols match these filters.</td></tr>";
    renderPager(pages);
  }

  function renderPager(pages) {
    var html = "";
    html += "<button data-page='" + (state.page - 1) + "' " + (state.page <= 1 ? "disabled" : "") + ">← Prev</button>";
    var win = [];
    for (var p = 1; p <= pages; p++) {
      if (p === 1 || p === pages || Math.abs(p - state.page) <= 2) win.push(p);
    }
    var last = 0;
    win.forEach(function (p) {
      if (p - last > 1) html += "<button disabled>…</button>";
      html += "<button data-page='" + p + "'" + (p === state.page ? " class='active'" : "") + ">" + p + "</button>";
      last = p;
    });
    html += "<button data-page='" + (state.page + 1) + "' " + (state.page >= pages ? "disabled" : "") + ">Next →</button>";
    $("pager").innerHTML = html;
  }

  // ---- detail view ----
  function findRow(key) {
    for (var i = 0; i < ROWS.length; i++) if (ROWS[i].slug === key) return ROWS[i];
    return null;
  }

  function renderDetail() {
    var box = $("detail");
    var r = state.detail ? findRow(state.detail) : null;
    if (!r) { box.hidden = true; box.innerHTML = ""; $("boardWrap").hidden = false; return; }
    $("boardWrap").hidden = true;
    box.hidden = false;
    var steps = farmSteps(r);
    box.innerHTML =
      "<button class='back' id='backBtn'>← Back to the board</button>" +
      "<h2>#" + r.rank + " · " + esc(r.name) + "</h2>" +
      "<p class='sub'>" + esc(r.category || "Uncategorized") + " · main chain " + esc(r.chain || "—") + "</p>" +
      "<div class='detail-grid'>" +
      cell("Implied value", fmtUsd(r.implied), true) +
      cell("TVL", fmtUsd(r.tvl), false) +
      cell("Multiple", r.multiple.toFixed(2) + "× <span style='font-size:13px;color:var(--muted)'>(" + r.peers + " peers" + (r.fallback ? ", fallback" : "") + ")</span>", false) +
      cell("Confidence", r.confidence, false) +
      "</div>" +
      "<h3>Why it ranks here</h3><p>" + esc(rationale(r)) + "</p>" +
      "<h3>Farm plan</h3>" +
      "<p>Cadence: " + esc(CADENCE) + " · Estimated gas: " + esc(r.cost) + "</p>" +
      "<ol class='steps'>" + steps.map(function (s) {
        return "<li><span>" + esc(s) + "</span></li>";
      }).join("") + "</ol>" +
      "<h3>Risks</h3><ul class='risks'>" +
      "<li>Smart-contract risk in the protocol itself.</li>" +
      "<li>A points program does not guarantee a token — a protocol can stay tokenless forever.</li>" +
      "<li>Never deposit more than you can lose, and never share a seed phrase.</li>" +
      "</ul>" +
      "<p class='meta-line'>Find the app on its DefiLlama page: defillama.com/protocol/" + esc(r.slug) +
      " — open the official site from there, never from a DM or an ad." +
      " · TVL 7d: " + (r.change7d == null ? "—" : (r.change7d > 0 ? "+" : "") + r.change7d.toFixed(1) + "%") +
      " · Listed " + (r.age == null ? "—" : r.age + "y ago") +
      " · Snapshot " + fetched + "</p>";
    $("backBtn").addEventListener("click", function () {
      state.detail = "";
      syncUrl();
      renderDetail();
      renderBoard();
      window.scrollTo({ top: 0 });
    });
    window.scrollTo({ top: 0 });
  }
  function cell(label, value, accent) {
    return "<div class='cell'><div class='label'>" + esc(label) + "</div><div class='value" + (accent ? " accent" : "") + "'>" + value + "</div></div>";
  }

  // ---- URL sync ----
  function syncUrl() {
    var p = new URLSearchParams();
    if (state.q) p.set("q", state.q);
    if (state.category) p.set("category", state.category);
    if (state.chain) p.set("chain", state.chain);
    if (state.confidence) p.set("confidence", state.confidence);
    if (state.sort !== "implied") p.set("sort", state.sort);
    if (state.detail) p.set("protocol", state.detail);
    else if (state.page > 1) p.set("page", String(state.page));
    var qs = p.toString();
    history.replaceState(null, "", qs ? "?" + qs : window.location.pathname);
  }

  // ---- events ----
  $("q").addEventListener("input", function (e) { state.q = e.target.value; state.page = 1; syncUrl(); renderBoard(); });
  $("category").addEventListener("change", function (e) { state.category = e.target.value; state.page = 1; syncUrl(); renderBoard(); });
  $("chain").addEventListener("change", function (e) { state.chain = e.target.value; state.page = 1; syncUrl(); renderBoard(); });
  $("confidence").addEventListener("change", function (e) { state.confidence = e.target.value; state.page = 1; syncUrl(); renderBoard(); });
  $("sort").addEventListener("change", function (e) { state.sort = e.target.value; state.page = 1; syncUrl(); renderBoard(); });
  $("reset").addEventListener("click", function () {
    state.q = ""; state.category = ""; state.chain = ""; state.confidence = "";
    state.sort = "implied"; state.page = 1; state.detail = "";
    $("q").value = ""; $("category").value = ""; $("chain").value = "";
    $("confidence").value = ""; $("sort").value = "implied";
    syncUrl(); renderDetail(); renderBoard();
  });
  $("rows").addEventListener("click", function (e) {
    var tr = e.target.closest("tr[data-key]");
    if (!tr) return;
    state.detail = tr.getAttribute("data-key");
    syncUrl(); renderDetail();
  });
  $("pager").addEventListener("click", function (e) {
    var b = e.target.closest("button[data-page]");
    if (!b || b.disabled) return;
    state.page = Math.max(1, parseInt(b.getAttribute("data-page"), 10) || 1);
    syncUrl(); renderBoard();
    document.getElementById("boardWrap").scrollIntoView();
  });

  renderDetail();
  renderBoard();
})();
